void process_lru_command(conn *c, token_t *tokens, size_t ntokens) {
    if (ntokens < 2) {
        // Not enough tokens to determine the command
        return;
    }

    if (strcmp(tokens[0].value, "tune") == 0) {
        if (ntokens != 6) {
            // Invalid number of tokens for 'tune' command
            return;
        }

        // Parse hot percentage
        double hot_percentage = atof(tokens[1].value);
        if (hot_percentage < 0 || hot_percentage > 100) {
            // Invalid hot percentage
            return;
        }

        // Parse warm percentage
        double warm_percentage = atof(tokens[2].value);
        if (warm_percentage < 0 || warm_percentage > 100) {
            // Invalid warm percentage
            return;
        }

        // Parse hot age factor
        double hot_age_factor = atof(tokens[3].value);
        if (hot_age_factor <= 0) {
            // Invalid hot age factor
            return;
        }

        // Parse warm age factor
        double warm_age_factor = atof(tokens[4].value);
        if (warm_age_factor <= 0) {
            // Invalid warm age factor
            return;
        }

        // Parse global age factor
        double global_age_factor = atof(tokens[5].value);
        if (global_age_factor <= 0) {
            // Invalid global age factor
            return;
        }

        // Update LRU settings
        c->lru_hot_percentage = hot_percentage;
        c->lru_warm_percentage = warm_percentage;
        c->lru_hot_age_factor = hot_age_factor;
        c->lru_warm_age_factor = warm_age_factor;
        c->lru_global_age_factor = global_age_factor;

    } else if (strcmp(tokens[0].value, "mode") == 0) {
        if (ntokens != 2) {
            // Invalid number of tokens for 'mode' command
            return;
        }

        // Parse LRU mode
        int mode = atoi(tokens[1].value);
        if (mode < 0 || mode > 2) {
            // Invalid LRU mode
            return;
        }

        // Set LRU mode
        c->lru_mode = mode;

    } else if (strcmp(tokens[0].value, "temp_ttl") == 0) {
        if (ntokens != 2) {
            // Invalid number of tokens for 'temp_ttl' command
            return;
        }

        // Parse temporary TTL
        int ttl = atoi(tokens[1].value);
        if (ttl < 0) {
            // Invalid TTL
            return;
        }

        // Set temporary TTL
        c->temp_ttl = ttl;
    } else {
        // Unknown command
        return;
    }
}

