void process_lru_command(conn *c, token_t *tokens, size_t ntokens) {
    if (ntokens < 2) {
        /* Invalid number of tokens */
        return;
    }

    if (strncmp(tokens[0].value, "tune", tokens[0].length) == 0) {
        if (ntokens != 5) {
            return;
        }

        int hot_pct, warm_pct, hot_age, warm_age;
        if (sscanf(tokens[1].value, "%d", &hot_pct) != 1 || hot_pct < 0 || hot_pct > 100) {
            return;
        }

        if (sscanf(tokens[2].value, "%d", &warm_pct) != 1 || warm_pct < 0 || warm_pct > 100) {
            return;
        }

        if (sscanf(tokens[3].value, "%d", &hot_age) != 1 || hot_age < 0) {
            return;
        }

        if (sscanf(tokens[4].value, "%d", &warm_age) != 1 || warm_age < 0) {
            return;
        }

        /* Update LRU settings */
        c->hot_pct = hot_pct;
        c->warm_pct = warm_pct;
        c->hot_age = hot_age;
        c->warm_age = warm_age;

    } else if (strncmp(tokens[0].value, "mode", tokens[0].length) == 0) {
        if (ntokens != 2) {
            return;
        }

        if (strncmp(tokens[1].value, "hot", tokens[1].length) == 0) {
            c->lru_mode = LRU_MODE_HOT;
        } else if (strncmp(tokens[1].value, "warm", tokens[1].length) == 0) {
            c->lru_mode = LRU_MODE_WARM;
        } else if (strncmp(tokens[1].value, "mixed", tokens[1].length) == 0) {
            c->lru_mode = LRU_MODE_MIXED;
        } else {
            return;
        }

    } else if (strncmp(tokens[0].value, "temp_ttl", tokens[0].length) == 0) {
        if (ntokens != 2) {
            return;
        }

        int temp_ttl;
        if (sscanf(tokens[1].value, "%d", &temp_ttl) != 1 || temp_ttl < 0) {
            return;
        }

        c->temp_ttl = temp_ttl;
    } else {
        return;
    }
}

